257	//判断一个字符是否是非终结符：文法中凡是作为规则左部出现过的字符都是非终结符
258	static bool is_non_terminal(const char c, const vector<rule>& rules) {
259		for (unsigned int i = 0; i < rules.size(); i++) {
260			if (rules[i].left == c) {
261				return true;
262			}
263		}
264		return false;
265	}
266	//求符号串ss的First集，visiting记录当前正在展开的非终结符，防止左递归文法导致无限递归
267	static set<char> firstOf(const string ss, const vector<rule>& rules, set<char>& visiting) {
268		set<char> result;
269		bool all_epsilon = true;//ss中的每个符号都能推出空串时，First集里才有“@”
270		for (unsigned int i = 0; i < ss.length(); i++) {
271			char c = ss[i];
272			if (c == '@') {
273				continue;//“@”本身就代表空串，不影响它后面的符号
274			}
275			if (!is_non_terminal(c, rules)) {
276				result.insert(c);//终结符直接进入First集
277				all_epsilon = false;
278				break;//终结符后面的符号对First集不再有贡献
279			}
280			if (visiting.count(c) > 0) {
281				all_epsilon = false;
282				break;//该非终结符正处在展开过程中，再展开下去就会陷入死循环
283			}
284			//非终结符：把它的每一个候选式的First集并进来
285			visiting.insert(c);
286			bool has_epsilon = false;
287			for (unsigned int j = 0; j < rules.size(); j++) {
288				if (rules[j].left != c) {
289					continue;
290				}
291				for (unsigned int k = 0; k < rules[j].right.size(); k++) {
292					set<char> sub = firstOf(rules[j].right[k], rules, visiting);
293					for (set<char>::iterator it = sub.begin(); it != sub.end(); it++) {
294						if (*it == '@') {
295							has_epsilon = true;//该候选式能推出空串，暂不收录“@”
296						}
297						else {
298							result.insert(*it);
299						}
300					}
301				}
302			}
303			visiting.erase(c);
304			if (!has_epsilon) {
305				all_epsilon = false;
306				break;//该非终结符推不出空串，后面的符号对First集不再有贡献
307			}
308		}
309		if (all_epsilon) {
310			result.insert('@');//整个符号串都能推出空串
311		}
312		return result;
313	}
314	F_set findFirst(const string ss, vector<rule> rules) {
315		F_set f_set;
316		f_set.is_first = true;
317		f_set.left = ss;
318		set<char> visiting;
319		f_set.right = firstOf(ss, rules, visiting);
320		return f_set;
321	}
322	vector<F_set> checkFirst(set<string> right_parts, vector<rule> rules) {
323		//逐个求出各条规则右部符号串的First集，重复的右部在set里已经合并，只会显示一次
324		vector<F_set> f_sets;
325		cout << "各规则右部的First集：" << endl;
326		for (set<string>::iterator it = right_parts.begin(); it != right_parts.end(); it++) {
327			F_set f_set = findFirst(*it, rules);
328			cout << "    " << f_set << endl;
329			f_sets.push_back(f_set);
330		}
331		cout << endl;
332		return f_sets;
333	}
334	//求非终结符的Follow集，visiting记录当前正在求Follow集的非终结符，防止规则相互引用导致无限递归
335	static set<char> followOf(const char non_terminal, const vector<rule>& rules, set<char>& visiting) {
336		set<char> result;
337		result.insert('#');//“#”是输入串的结束标志，任何非终结符的Follow集里都带上它
338		visiting.insert(non_terminal);
339		for (unsigned int i = 0; i < rules.size(); i++) {
340			for (unsigned int j = 0; j < rules[i].right.size(); j++) {
341				const string& part = rules[i].right[j];
342				//同一个候选式中该非终结符可能出现多次，逐个位置考察
343				string::size_type pos = part.find(non_terminal);
344				while (pos != string::npos) {
345					bool at_end = true;//其后的符号串是否能推出空串（出现在末尾时同样成立）
346					if (pos + 1 < part.length()) {
347						//紧跟其后的符号串的First集去掉“@”之后并入Follow集
348						set<char> visiting_first;
349						set<char> first = firstOf(part.substr(pos + 1), rules, visiting_first);
350						at_end = false;
351						for (set<char>::iterator it = first.begin(); it != first.end(); it++) {
352							if (*it == '@') {
353								at_end = true;//后继符号串能推出空串，还要并入规则左部的Follow集
354							}
355							else {
356								result.insert(*it);
357							}
358						}
359					}
360					if (at_end && visiting.count(rules[i].left) == 0) {
361						//位于规则末尾时，规则左部的Follow集整个并入
362						set<char> parent = followOf(rules[i].left, rules, visiting);
363						result.insert(parent.begin(), parent.end());
364					}
365					pos = part.find(non_terminal, pos + 1);
366				}
367			}
368		}
369		visiting.erase(non_terminal);
370		return result;
371	}
372	F_set findFollow(const char non_terminal, vector<rule> rules) {
373		F_set f_set;
374		f_set.is_first = false;
375		f_set.left = non_terminal;
376		set<char> visiting;
377		f_set.right = followOf(non_terminal, rules, visiting);
378		return f_set;
379	}
380	vector<F_set> checkFollow(set<char> non_terminal, vector<rule> rules) {
381		//逐个求出各个非终结符的Follow集
382		vector<F_set> f_sets;
383		cout << "各非终结符的Follow集：" << endl;
384		for (set<char>::iterator it = non_terminal.begin(); it != non_terminal.end(); it++) {
385			F_set f_set = findFollow(*it, rules);
386			cout << "    " << f_set << endl;
387			f_sets.push_back(f_set);
388		}
389		cout << endl;
390		return f_sets;
391	}
392	LL_1_table LL_1(set<char>& terminal, set<char>& non_terminal, vector<rule> rules) {
393		LL_1_table table;
394		//行表头：按规则书写的先后顺序排列非终结符，这样第一行对应的就是文法的开始符号
395		for (unsigned int i = 0; i < rules.size(); i++) {
396			if (find(table.row.begin(), table.row.end(), rules[i].left) == table.row.end()) {
397				table.row.push_back(rules[i].left);
398			}
399		}
400		//只出现在右部、没有产生式的非终结符同样占一行，避免分析表缺行
401		for (set<char>::iterator it = non_terminal.begin(); it != non_terminal.end(); it++) {
402			if (find(table.row.begin(), table.row.end(), *it) == table.row.end()) {
403				table.row.push_back(*it);
404			}
405		}
406		//列表头：全部终结符再加上输入串的结束标志“#”，“#”固定放在最后一列
407		terminal.insert('#');
408		for (set<char>::iterator it = terminal.begin(); it != terminal.end(); it++) {
409			if (*it != '#' && *it != '@') {
410				table.col.push_back(*it);
411			}
412		}
413		table.col.push_back('#');
414		//表中每个单元格先放一条空规则，能填入产生式的单元格随后再覆盖
415		rule blank;
416		blank.left = 0;
417		table.rules.assign(table.row.size() * table.col.size(), blank);
418	
419		//逐条候选式填表：候选式的First集里有哪个终结符，就把它填到对应的单元格里
420		for (unsigned int i = 0; i < rules.size(); i++) {
421			//行号由规则左部决定
422			vector<char>::iterator row_it = find(table.row.begin(), table.row.end(), rules[i].left);
423			if (row_it == table.row.end()) {
424				continue;
425			}
426			unsigned int r = (unsigned int)(row_it - table.row.begin());
427			for (unsigned int j = 0; j < rules[i].right.size(); j++) {
428				//单元格里存放的是“左部::=某一个候选式”这样一条单候选式规则
429				rule cell;
430				cell.left = rules[i].left;
431				cell.right.push_back(rules[i].right[j]);
432	
433				F_set first = findFirst(rules[i].right[j], rules);
434				set<char> heads = first.right;
435				//候选式能推出空串时，改用左部的Follow集来决定填表的位置
436				if (heads.count('@') > 0) {
437					F_set follow = findFollow(rules[i].left, rules);
438					heads.insert(follow.right.begin(), follow.right.end());
439				}
440				for (set<char>::iterator it = heads.begin(); it != heads.end(); it++) {
441					if (*it == '@') {
442						continue;//“@”自身不是终结符，不占分析表的列
443					}
444					vector<char>::iterator col_it = find(table.col.begin(), table.col.end(), *it);
445					if (col_it == table.col.end()) {
446						continue;
447					}
448					unsigned int c = (unsigned int)(col_it - table.col.begin());
449					table.rules[r * table.col.size() + c] = cell;
450				}
451			}
452		}
453		return table;
454	}
455	ostream& operator << (ostream& out, LL_1_table table) {
456		out << "LL(1)分析表如下：" << endl;
457		//列表头：第一列留给非终结符，其余各列依次对应一个终结符
458		out << setw(8) << " ";
459		for (unsigned int j = 0; j < table.col.size(); j++) {
460			out << setw(12) << table.col[j];
461		}
462		out << endl;
463		//逐行输出：行首是非终结符，其后是各个单元格里的产生式，空单元格留白
464		for (unsigned int i = 0; i < table.row.size(); i++) {
465			out << setw(8) << table.row[i];
466			for (unsigned int j = 0; j < table.col.size(); j++) {
467				ostringstream cell;
468				unsigned int at = i * table.col.size() + j;
469				if (at < table.rules.size() && !table.rules[at].right.empty()) {
470					cell << table.rules[at];
471				}
472				out << setw(12) << cell.str();
473			}
474			out << endl;
475		}
476		out << endl;
477		return out;
478	}
479	void print_state(stack<char> analysis_s, stack<char> input_s, rule& rule_temp) {
480		//分析栈按“栈底到栈顶”的顺序输出，栈底的“#”排在最左边
481		string analysis = "";
482		while (!analysis_s.empty()) {
483			analysis = string(1, analysis_s.top()) + analysis;
484			analysis_s.pop();
485		}
486		//输入栈按“栈顶到栈底”的顺序输出，正好是剩余的输入串
487		string input = "";
488		while (!input_s.empty()) {
489			input += input_s.top();
490			input_s.pop();
491		}
492		//所用产生式：右部为空说明这一步不是推导而是终结符匹配
493		ostringstream action;
494		if (!rule_temp.right.empty()) {
495			action << rule_temp;
496		}
497		else if (rule_temp.left != 0) {
498			action << "“" << rule_temp.left << "”匹配";
499		}
500		cout << setw(20) << analysis << setw(20) << input << setw(20) << action.str() << endl;
501	}
502	void syntacticAnalysis(LL_1_table table) {
503		cout << endl << "接下来进行语法分析" << endl << "请输入字符串：" << endl;
504		string input;
505		cin >> input;
506	
507		//分析栈：栈底压入结束标志“#”，其上压入文法的开始符号，即分析表的第一行
508		stack<char> analysis_s;
509		analysis_s.push('#');
510		if (!table.row.empty()) {
511			analysis_s.push(table.row[0]);
512		}
513		//输入栈：结束标志“#”压在栈底，待分析的字符串倒序入栈，栈顶就是当前输入符号
514		stack<char> input_s;
515		input_s.push('#');
516		for (int i = (int)input.length() - 1; i >= 0; i--) {
517			input_s.push(input[i]);
518		}
519	
520		//分析是否成功的标志，一旦出现无法匹配或者查不到产生式的情况就置为false
521		bool success = true;
522		if (table.row.empty()) {
523			cout << "没有可用的文法规则，无法进行语法分析" << endl;
524			success = false;
525		}
526	
527		//分析过程表头
528		cout << endl << setw(20) << "分析栈" << setw(20) << "剩余输入串" << setw(20) << "所用产生式" << endl;
529	
530		//表驱动的分析过程：栈顶是非终结符就查表展开，是终结符就与当前输入符号匹配
531		rule rule_temp;//本步骤所用的产生式，右部为空表示该步骤只是一次终结符匹配
532		rule_temp.left = 0;
533		unsigned int step = 0;
534		while (success) {
535			char top = analysis_s.top();
536			char cur = input_s.top();
537			if (top == '#' && cur == '#') {
538				//分析栈与输入串同时到达结束标志，分析成功结束
539				rule_temp.left = 0;
540				rule_temp.right.clear();
541				print_state(analysis_s, input_s, rule_temp);
542				break;
543			}
544			if (++step > 10000) {
545				cout << "推导步骤过多，文法可能存在左递归，分析终止" << endl;
546				success = false;
547				break;
548			}
549			vector<char>::iterator row_it = find(table.row.begin(), table.row.end(), top);
550			if (row_it == table.row.end()) {
551				//栈顶是终结符：与当前输入符号相同才能一起弹出，否则分析失败
552				if (top != cur) {
553					cout << "栈顶终结符" << top << "与当前输入符号" << cur << "不匹配，分析终止" << endl;
554					success = false;
555					break;
556				}
557				rule_temp.left = top;
558				rule_temp.right.clear();
559				print_state(analysis_s, input_s, rule_temp);
560				analysis_s.pop();
561				input_s.pop();
562				continue;
563			}
564			//栈顶是非终结符：用当前输入符号查分析表，取出对应的产生式
565			vector<char>::iterator col_it = find(table.col.begin(), table.col.end(), cur);
566			unsigned int at = 0;
567			if (col_it != table.col.end()) {
568				at = (unsigned int)(row_it - table.row.begin()) * table.col.size() + (unsigned int)(col_it - table.col.begin());
569			}
570			if (col_it == table.col.end() || at >= table.rules.size() || table.rules[at].right.empty()) {
571				cout << "分析表中(" << top << "," << cur << ")处为空，分析终止" << endl;
572				success = false;
573				break;
574			}
575			rule_temp = table.rules[at];
576			print_state(analysis_s, input_s, rule_temp);
577			//用产生式右部替换栈顶的非终结符，右部为“@”时只弹出不压入
578			analysis_s.pop();
579			string right = rule_temp.right[0];
580			if (right != "@") {
581				//右部倒序入栈，保证最左边的符号处在栈顶
582				for (int i = (int)right.length() - 1; i >= 0; i--) {
583					analysis_s.push(right[i]);
584				}
585			}
586		}
587	
588		cout << endl << "字符串" << input;
589		if (!success) {
590			cout << "不";
591		}
592		cout << "是该文法的句子" << endl;
593	}
