49	bool preProcess(const string fileName, const string newFileName) {
50		printTips("开始预处理");
51		//打开原始源程序文件
52		ifstream in(fileName.c_str());
53		if (!in) {
54			cout << "源程序文件打开失败：" << fileName << endl;
55			return false;
56		}
57		//将源程序整体读入字符缓冲区，后续清洗阶段在此缓冲区上继续加工
58		string code = "";
59		char ch;
60		while (in.get(ch)) {
61			code += ch;
62		}
63		in.close();
64	
65		//第一步：删除注释，支持“//”单行注释和可以跨行的“/* */”块注释，
66		//其余字符原样保留，交给后面的空白清洗阶段继续处理
67		string noComment = "";
68		for (unsigned int i = 0; i < code.length(); i++) {
69			if (code[i] == '/' && i + 1 < code.length() && code[i + 1] == '/') {
70				//单行注释：一直跳到行尾，换行符本身保留
71				i += 2;
72				while (i < code.length() && code[i] != '\n') {
73					i++;
74				}
75				if (i < code.length()) {
76					noComment += code[i];
77				}
78			}
79			else if (code[i] == '/' && i + 1 < code.length() && code[i + 1] == '*') {
80				//块注释：一直跳到配对的“*/”，中途可以跨越任意多行
81				i += 2;
82				while (i + 1 < code.length() && !(code[i] == '*' && code[i + 1] == '/')) {
83					i++;
84				}
85				i++;//此时i停在“*”上，再前进一位越过“/”，循环的i++负责越过其后
86			}
87			else {
88				noComment += code[i];
89			}
90		}
91		code = noComment;
92	
93		//第二步：清洗空白字符，删除回车换行与制表符，并把连续的多个空格压缩成一个
94		string cleaned = "";
95		for (unsigned int i = 0; i < code.length(); i++) {
96			char c = code[i];
97			if (c == '\n' || c == '\r' || c == '\t' || c == '\v' || c == '\f') {
98				continue;//回车换行、制表符直接丢弃
99			}
100			if (c == ' ' && !cleaned.empty() && cleaned[cleaned.length() - 1] == ' ') {
101				continue;//连续空格只保留第一个
102			}
103			cleaned += c;
104		}
105		code = cleaned;
106	
107		//将预处理后的源程序以字符流的形式显示出来
108		cout << "预处理后的源程序字符流如下：" << endl;
109		cout << code << endl << endl;
110	
111		//输出到预处理结果文件
112		ofstream out(newFileName.c_str());
113		if (!out) {
114			cout << "预处理结果文件创建失败：" << newFileName << endl;
115			return false;
116		}
117		out << code;
118		out.close();
119		cout << "预处理结果已保存至：" << newFileName << endl << endl;
120		printTips("预处理已完成");
121		return true;
122	}
