152	static map<string, int> buildWordTypeTable() {
153		map<string, int> table;
154		table["void"] = 1;
155		table["main"] = 2;
156		table["int"] = 3;
157		table["cout"] = 4;
158		table["return"] = 5;
159		table["("] = 6;
160		table[")"] = 7;
161		table["{"] = 8;
162		table["}"] = 9;
163		table["<<"] = 10;
164		table[";"] = 11;
165		table[","] = 12;
166		table["="] = 13;
167		table["*"] = 14;
168		table["/"] = 15;
169		return table;
