123	static string cell(LL_1_table& t, char nt, char term) {
124		int i = -1, j = -1;
125		for (unsigned int r = 0; r < t.row.size(); r++) {
126			if (t.row[r] == nt) {
127				i = (int)r;
128			}
129		}
130		for (unsigned int c = 0; c < t.col.size(); c++) {
131			if (t.col[c] == term) {
132				j = (int)c;
133			}
134		}
135		if (i < 0 || j < 0) {
136			return "?";
137		}
138		rule r = t.rules[i * t.col.size() + j];
139		if (r.right.empty()) {
140			return "";
141		}
142		ostringstream os;
143		os << r;
144		return os.str();
145	}
